import{_ as s,a0 as i,w as r,s as a,ao as u,I as t,a1 as n,A as p,x as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现 | LCTT x X-CMD","titleTemplate":false,"description":"“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop","title":"“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现","tag":"201407","desc":""},"relativePath":"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop.md","filePath":"[post].md"}'),m={name:"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop.md"};function S(d,e,h,k,O,E){const o=i("Link");return r(),a("div",null,[e[12]||(e[12]=u('<h1 id="simple-dock-gnome-shell扩展乾坤大挪移-钟爱应用桌面展现" tabindex="-1">“Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现 <a class="header-anchor" href="#simple-dock-gnome-shell扩展乾坤大挪移-钟爱应用桌面展现" aria-label="Permalink to ““Simple Dock” GNOME Shell扩展乾坤大挪移，钟爱应用桌面展现”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/07/screenshot_815_1.jpg" alt=""></p><p><strong>我爱GNOME Shell，但是我痛恨的是费力从隐藏屏幕中找到我所钟爱的应用或者在我正运行的应用间切换。</strong></p><p>这么说，听起来就像我是个老古董，像是一个UX勒德分子，也像是某个过分沉溺于Unity可用性瘾君子，但我，像阅读本文的许多人一样，喜欢将app启动器/切换器放到桌面上。这是一个用户所熟悉并且快捷的工作方式。</p><p>而GNOME Shell，从设计上看，却完全是个不同的世界。它将所有这一切隐藏起来 —— 从消息中心和通知，到工作区和应用列表。它弱化了审美效果，包含了这样的道理：帮助用户专注于最重要的部分。</p><p>但是对我而言，我的桌面需要的不仅仅是一个美化的相框。</p><h3 id="gnome-shell之美" tabindex="-1">GNOME Shell之美 <a class="header-anchor" href="#gnome-shell之美" aria-label="Permalink to “GNOME Shell之美”">​</a></h3><p>抛开我自己的偏好，隐藏应用是GNOME Shell之美的一部分。它带来了默认的桌面体验：用户友好，稳健以及可预见性——而且也完全可扩展。因此，它也附带有大量的扩展组件以迎合不同用户的需要、职业和希望，包括传统应用菜单，桌面停靠栏，以及甚至是Ubuntu Unity Dash的复制品！</p><p>在本文中，我仅仅关注那个能满足我需要的扩展：它有个恰如其分的名字<strong>Simple Dock</strong>。Simple Dock获取GNOME Shell应用网格以及收藏栏，并可以将它放到任何我想要放的不引人注目的位置：桌面上。</p><p>目前为止，它只支持放置在屏幕底部，只提供了最小的设置项。虽然是最小的，但我觉得所有这些设置已经能满足我的需要：</p><ul><li>智能自动隐藏</li><li>最小化/还原应用窗口</li><li>拖放收藏</li><li>覆盖活动启动按钮</li></ul><p>你也想要吗？如果你正在Ubuntu 13.10或更高版本上使用GNOME Shell，那么你可以使用它。只需在支持的浏览器（Firefox, GNOME Web之类）中访问下面的链接就可以导航到GNOME扩展页面，然后将页面上开个从“off”拖动到“on”上。</p>',12)),t("ul",null,[t("li",null,[n(o,{href:"https://extensions.gnome.org/extension/815/simple-dock/"},{default:p(()=>[...e[0]||(e[0]=[l("GNOME Shell扩展中的Simple Dock",-1)])]),_:1})])]),e[13]||(e[13]=t("p",null,"要调整Simple Dock设置，点击GNOME扩展页面上的齿轮图标，或者通过GNOME优化工具这样的桌面应用程序来设置。",-1)),e[14]||(e[14]=t("hr",null,null,-1)),t("p",null,[e[2]||(e[2]=l("via: ",-1)),n(o,{href:"http://www.omgubuntu.co.uk/2014/07/simple-dock-gnome-shell-extension"},{default:p(()=>[...e[1]||(e[1]=[l("http://www.omgubuntu.co.uk/2014/07/simple-dock-gnome-shell-extension",-1)])]),_:1})]),t("p",null,[e[5]||(e[5]=l("译者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:p(()=>[...e[3]||(e[3]=[l("GOLinux",-1)])]),_:1}),e[6]||(e[6]=l(" 校对：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...e[4]||(e[4]=[l("Caroline",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=l("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[7]||(e[7]=[l("LCTT",-1)])]),_:1}),e[10]||(e[10]=l(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...e[8]||(e[8]=[l("Linux中国",-1)])]),_:1}),e[11]||(e[11]=l(" 荣誉推出",-1))])])}const f=s(m,[["render",S]]);export{T as __pageData,f as default};
